python3 - <<'PY'
import subprocess, re, collections
branches=['rachel','monica','phoebe','joey','chandler','ross']
missing=[]
dup=collections.Counter()
for b in branches:
    shas=subprocess.check_output(['git','rev-list','--reverse',f'origin/friend/{b}'],text=True).split()
    for sha in shas:
        body=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' not in body: continue
        m=re.search(r'^Episode:\s*(.+)$',body,re.M)
        ep=m.group(1).strip() if m else None
        if not ep: 
            print('NO EP', b, sha); continue
        # read file from origin/main? use local main worktree maybe fetch
        try:
            content=subprocess.check_output(['git','show',f'origin/main:{ep}.md'],text=True)
        except Exception as e:
            print('FILE MISSING', ep, e); continue
        cnt=content.count(sha)
        if cnt==0:
            missing.append((b,ep,sha))
        if cnt>1:
            dup[(b,ep,sha)] += cnt
print('missing count', len(missing))
for x in missing: print('MISSING', x)
print('dup count', len(dup))
for x in dup: print('DUP', x, dup[x])
PY
